/**
 * @file fuzz_config.c
 * @brief libFuzzer harness for the configuration-file parser.
 *
 * Drives parse_config_file() with fuzzer-generated bytes to expose crashes,
 * undefined behavior, and memory leaks in section / key / value parsing, the
 * URL and integer/boolean coercions, the regex pre-check, and the
 * overlong-line rejection. The buffer is fed through fmemopen() exactly as the
 * CMocka suite does (tests/test_suite.c), so the harness exercises the same
 * code path. The PAM handle is NULL (the parser only uses it for audit logs,
 * which are NULL-safe), matching the CMocka calls.
 *
 * @project     pam_oidc_device
 * @repository  https://github.com/ncsa/pam_oidc_device
 * @maintainer  National Center for Supercomputing Applications (NCSA)
 * @license     MIT License
 *
 * Copyright (c) 2026 The Board of Trustees of the University of Illinois.
 * SPDX-License-Identifier: MIT
 */

#include "pam_oidc_device.h"

#include <stdio.h>
#include <string.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    /* NUL-terminate a capped copy of the fuzzer buffer; the parser reads lines
     * from a stream and never relies on embedded NULs. */
    static char buf[1u << 20];
    size_t n = size < sizeof(buf) - 1 ? size : sizeof(buf) - 1;
    memcpy(buf, data, n);
    buf[n] = '\0';

    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    FILE *fp = fmemopen(buf, strlen(buf), "r");
    if (fp) {
        parse_config_file(fp, &cfg, NULL);
        fclose(fp);
    }

    /* Scrub any secret (client_secret) parsed into the stack config. */
    secure_memzero(&cfg, sizeof(cfg));
    secure_memzero(buf, sizeof(buf));
    return 0;
}
